func (knownAttacksCodec) ValidateConfig(ctx context.Context, config tfsdk.Config) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	var model knownAttacksResourceModel
	diagnostics.Append(config.Get(ctx, &model)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	return (knownAttacksCodec{}).validateConfigs(ctx, model.Configs, diagnostics)
}

func (knownAttacksCodec) ValidateTemplateConfig(ctx context.Context, config tfsdk.Config) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	var model wafmodule.TemplateModel
	diagnostics.Append(config.Get(ctx, &model)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	return (knownAttacksCodec{}).validateConfigs(ctx, model.Configs, diagnostics)
}

func (knownAttacksCodec) validateConfigs(ctx context.Context, configs types.Object, diagnostics diag.Diagnostics) diag.Diagnostics {
	if configs.IsNull() || configs.IsUnknown() {
		return diagnostics
	}
	var values knownAttacksConfigsModel
	diagnostics.Append(configs.As(ctx, &values, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return diagnostics
	}
	if !values.Action.IsNull() && !values.Action.IsUnknown() && !knownAttacksConfigActionValid(values.Action.ValueString()) {
		diagnostics.AddError("Invalid known attacks action", "action must be one of alert, alert_deny, deny_no_log.")
	}
	if !values.SensitivityLevel.IsNull() && !values.SensitivityLevel.IsUnknown() && !knownAttacksConfigSensitivityLevelValid(values.SensitivityLevel.ValueInt64()) {
		diagnostics.AddError("Invalid known attacks sensitivity_level", "sensitivity_level must be one of 1, 2, 3, 4.")
	}

	diagnostics.Append(knownAttacksValidateConfiguredSigExceptRules(ctx, values.SigExceptRules)...)

	diagnostics.Append(knownAttacksValidateConfiguredStxExceptRules(ctx, values.StxExceptRules)...)
	return diagnostics
}

func (knownAttacksCodec) BuildPatch(ctx context.Context, config tfsdk.Config, plan tfsdk.Plan, _ tfsdk.State) (wafmodule.Patch, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	var configured, planned knownAttacksResourceModel
	diagnostics.Append(config.Get(ctx, &configured)...)
	diagnostics.Append(plan.Get(ctx, &planned)...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return (knownAttacksCodec{}).buildConfigsPatch(ctx, configured.Configs, planned.Configs, diagnostics)
}

func (knownAttacksCodec) BuildTemplatePatch(ctx context.Context, config tfsdk.Config, plan tfsdk.Plan, _ tfsdk.State) (wafmodule.Patch, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	var configured, planned wafmodule.TemplateModel
	diagnostics.Append(config.Get(ctx, &configured)...)
	diagnostics.Append(plan.Get(ctx, &planned)...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return (knownAttacksCodec{}).buildConfigsPatch(ctx, configured.Configs, planned.Configs, diagnostics)
}

func (knownAttacksCodec) buildConfigsPatch(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (wafmodule.Patch, diag.Diagnostics) {
	if configured.IsNull() {
		return knownAttacksPatch{}, diagnostics
	}
	if configured.IsUnknown() || planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown known attacks configuration", "The configs block must be known during apply.")
		return nil, diagnostics
	}

	var configValues, planValues knownAttacksConfigsModel
	diagnostics.Append(configured.As(ctx, &configValues, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planValues, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return nil, diagnostics
	}

	patch := knownAttacksPatch{}
	patch.Action, diagnostics = knownAttacksConfiguredString(configValues.Action, planValues.Action, "action", diagnostics)
	if patch.Action.Set && !knownAttacksConfigActionValid(patch.Action.Value) {
		diagnostics.AddError("Invalid known attacks action", "action must be one of alert, alert_deny, deny_no_log.")
	}
	patch.ArithmeticSqlInject, diagnostics = knownAttacksConfiguredBool(configValues.ArithmeticSqlInject, planValues.ArithmeticSqlInject, "arithmetic_sql_inject", diagnostics)
	patch.ConditionSqlInject, diagnostics = knownAttacksConfiguredBool(configValues.ConditionSqlInject, planValues.ConditionSqlInject, "condition_sql_inject", diagnostics)
	patch.CrossSiteScript, diagnostics = knownAttacksConfiguredBool(configValues.CrossSiteScript, planValues.CrossSiteScript, "cross_site_script", diagnostics)
	patch.CrossSiteScriptExt, diagnostics = knownAttacksConfiguredBool(configValues.CrossSiteScriptExt, planValues.CrossSiteScriptExt, "cross_site_script_ext", diagnostics)
	patch.EmbedSqlInject, diagnostics = knownAttacksConfiguredBool(configValues.EmbedSqlInject, planValues.EmbedSqlInject, "embed_sql_inject", diagnostics)
	patch.GenericAttacks, diagnostics = knownAttacksConfiguredBool(configValues.GenericAttacks, planValues.GenericAttacks, "generic_attacks", diagnostics)
	patch.GenericAttacksExt, diagnostics = knownAttacksConfiguredBool(configValues.GenericAttacksExt, planValues.GenericAttacksExt, "generic_attacks_ext", diagnostics)
	patch.HtmlAttrXssInject, diagnostics = knownAttacksConfiguredBool(configValues.HtmlAttrXssInject, planValues.HtmlAttrXssInject, "html_attr_xss_inject", diagnostics)
	patch.HtmlCssXssInject, diagnostics = knownAttacksConfiguredBool(configValues.HtmlCssXssInject, planValues.HtmlCssXssInject, "html_css_xss_inject", diagnostics)
	patch.HtmlTagXssInject, diagnostics = knownAttacksConfiguredBool(configValues.HtmlTagXssInject, planValues.HtmlTagXssInject, "html_tag_xss_inject", diagnostics)
	patch.JsFuncXssInject, diagnostics = knownAttacksConfiguredBool(configValues.JsFuncXssInject, planValues.JsFuncXssInject, "js_func_xss_inject", diagnostics)
	patch.JsVarXssInject, diagnostics = knownAttacksConfiguredBool(configValues.JsVarXssInject, planValues.JsVarXssInject, "js_var_xss_inject", diagnostics)
	patch.KnownExploits, diagnostics = knownAttacksConfiguredBool(configValues.KnownExploits, planValues.KnownExploits, "known_exploits", diagnostics)
	patch.LineComments, diagnostics = knownAttacksConfiguredBool(configValues.LineComments, planValues.LineComments, "line_comments", diagnostics)
	patch.SensitivityLevel, diagnostics = knownAttacksConfiguredInt64(configValues.SensitivityLevel, planValues.SensitivityLevel, "sensitivity_level", diagnostics)
	patch.SqlFuncInject, diagnostics = knownAttacksConfiguredBool(configValues.SqlFuncInject, planValues.SqlFuncInject, "sql_func_inject", diagnostics)
	patch.SqlInject, diagnostics = knownAttacksConfiguredBool(configValues.SqlInject, planValues.SqlInject, "sql_inject", diagnostics)
	patch.SqlInjectExt, diagnostics = knownAttacksConfiguredBool(configValues.SqlInjectExt, planValues.SqlInjectExt, "sql_inject_ext", diagnostics)
	patch.StackSqlInject, diagnostics = knownAttacksConfiguredBool(configValues.StackSqlInject, planValues.StackSqlInject, "stack_sql_inject", diagnostics)
	patch.Status, diagnostics = knownAttacksConfiguredBool(configValues.Status, planValues.Status, "status", diagnostics)
	patch.Trojans, diagnostics = knownAttacksConfiguredBool(configValues.Trojans, planValues.Trojans, "trojans", diagnostics)

	patch.SigExceptRules, diagnostics = knownAttacksBuildConfiguredSigExceptRules(ctx, configValues.SigExceptRules, planValues.SigExceptRules, diagnostics)

	patch.StxExceptRules, diagnostics = knownAttacksBuildConfiguredStxExceptRules(ctx, configValues.StxExceptRules, planValues.StxExceptRules, diagnostics)
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return patch, diagnostics
}

