		plannedItem := planItems[index]
		location := fmt.Sprintf("stx_except_rules item %d", index+1)
		item := knownAttacksStxExceptRulesWireItem{
			Index: index + 1,
		}
		attack_catValue, ok := knownAttacksPlannedRequiredString(configuredItem.AttackCat, plannedItem.AttackCat, location+" attack_cat", &diagnostics)
		if !ok {
			continue
		}
		knownAttacksValidateString(location, " attack_cat", attack_catValue, 0, 0, &diagnostics)
		if !knownAttacksStxExceptRulesAttackCatValid(attack_catValue) {
			diagnostics.AddError("Invalid known attacks item", location+" attack_cat must be one of Cross Site Scripting (Syntax Based Detection), SQL Injection (Syntax Based Detection).")
		}
		item.AttackCat = attack_catValue
		attack_nameValue, ok := knownAttacksPlannedRequiredString(configuredItem.AttackName, plannedItem.AttackName, location+" attack_name", &diagnostics)
		if !ok {
			continue
		}
		knownAttacksValidateString(location, " attack_name", attack_nameValue, 0, 0, &diagnostics)
		if !knownAttacksStxExceptRulesAttackNameValid(attack_nameValue) {
			diagnostics.AddError("Invalid known attacks item", location+" attack_name must be one of Arithmetic Operation Based Boolean Injection, Condition Based Boolean Injection, Embedded Queries SQL Injection, HTML Attribute Based XSS Injection, HTML CSS Based XSS Injection, HTML Tag Based XSS Injection, Javascript Function Based XSS Injection, Javascript Variable Based XSS Injection, Line Comments, SQL Function Based Boolean Injection, Stacked Queries SQL Injection.")
		}
		item.AttackName = attack_nameValue
		item.Cookie = knownAttacksStxExceptRulesBuildNestedCookie(ctx, configuredItem.Cookie, plannedItem.Cookie, location, &diagnostics)
